insert into public.proj_items(slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order) values ('pj_wk_book','project','arabic','project','كتابي المصور','i_book',array['a6','g1','g2']::text[],'اللغة العربية','ربط الكلمة بالصورة والكتابة','easy','نصنع خلال أسبوع كتابا صغيرا فيه صورة وجملة قصيرة في كل صفحة.','أن أصنع كتابا صغيرا مصورا وأكتب تحت كل صورة كلمة أو جملة قصيرة.',20,'weekly',$j${"goal": "أن أصنع كتابا صغيرا مصورا وأكتب تحت كل صورة كلمة أو جملة قصيرة.", "tools": ["ورق أبيض أو دفتر صغير", "أقلام تلوين", "قلم رصاص", "شريط لاصق"], "steps": [{"t": "نختار موضوعا نحبه مثل الحيوانات أو بيتنا أو الفواكه.", "i": "i_book", "p": "اترك الطفل يختار الموضوع بنفسه.", "g": "اليوم الأول"}, {"t": "نجهز أربع صفحات ونرقمها من ١ إلى ٤.", "i": "x_paper", "g": "اليوم الأول"}, {"t": "نرسم الصورة الأولى في الصفحة الأولى بألوان جميلة.", "i": "i_brush", "g": "اليوم الثاني"}, {"t": "نرسم الصورة الثانية في الصفحة الثانية.", "i": "i_palette", "g": "اليوم الثاني"}, {"t": "نكتب تحت الصورة الأولى كلمة أو جملة قصيرة بخط واضح.", "i": "i_pencil", "p": "إن احتاج الطفل ساعده بنطق الكلمة، ولا تكتب بدلا عنه.", "g": "اليوم الثالث"}, {"t": "نكتب تحت بقية الصور ما نريد.", "i": "i_pencils", "g": "اليوم الثالث"}, {"t": "نصمم الغلاف ونكتب عليه اسم الكتاب واسمنا.", "i": "i_notebook", "g": "اليوم الرابع"}, {"t": "نربط الصفحات معا بشريط لاصق من الجانب.", "i": "i_blocks", "g": "اليوم الرابع"}, {"t": "نقرأ كتابنا بصوت واضح لأحد أفراد الأسرة.", "i": "i_sound", "p": "صفق له واسأله عن صفحته المفضلة.", "g": "اليوم الخامس"}], "safety": "نعمل بإشراف شخص بالغ ونستعمل أقلام تلوين وأقلام رصاص عادية وورقا نظيفا.", "outcome": "أصنع كتابا صغيرا وأقرأ ما كتبته بنفسي.", "adult": true, "skills": ["كتابة الكلمات", "الرسم والتعبير", "القراءة بصوت واضح"], "qs": [{"q": "ما الذي نكتبه تحت الصورة؟", "o": ["كلمة أو جملة عن الصورة", "رقم هاتف", "اسم شارع بيتنا"], "why": "نكتب ما يصف الصورة فقط ولا نكتب معلومات خاصة."}, {"q": "متى نقرأ الكتاب لأسرتنا؟", "o": ["في اليوم الأخير بعد أن نكمله", "قبل أن نرسم الصور", "لا نقرؤه أبدا"], "why": "نقرأ الكتاب بعد إكماله لنفرح بما أنجزناه."}], "reflect": "ما أجمل صفحة في كتابك ولماذا؟ وما الموضوع الذي ستكتب عنه في كتابك القادم؟", "parent": "ساعد طفلك بالأسئلة مثل ماذا سترسم في الصفحة التالية؟ ولا تكتب أو ترسم بدلا عنه. شجعه على ما أنجزه كل يوم ولا تقارنه بغيره.", "res": [{"label": "قصص المكتبة", "href": "stories/"}, {"label": "بطاقات المكتبة التعليمية", "href": "cards/"}, {"label": "اللغة والبطاقات", "href": "language/"}]}$j$::jsonb,'{}'::jsonb,false,'draft',101) on conflict (slug) do nothing;
insert into public.proj_items(slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order) values ('pj_wk_numbers','project','math','project','مجموعة الأعداد','i_numbers',array['a5','a6','g1']::text[],'الرياضيات','العد ومقارنة الكميات','easy','نجمع أشياء من البيت ونعدها ونقارن بين المجموعات خلال أسبوع.','أن أعد مجموعات من ١ إلى ١٠ وأقارن بين مجموعتين بقولي أكثر أو أقل.',15,'weekly',$j${"goal": "أن أعد مجموعات من ١ إلى ١٠ وأقارن بين مجموعتين بقولي أكثر أو أقل.", "tools": ["كيس أو علبة كبيرة", "أشياء من البيت مثل الأقلام والملاعق", "ورق وقلم", "أقلام تلوين"], "steps": [{"t": "نجمع عشرة أشياء من البيت في العلبة.", "i": "x_box", "p": "اختر معه أشياء آمنة وكبيرة.", "g": "اليوم الأول"}, {"t": "نخرجها واحدا واحدا ونعدها بصوت عال.", "i": "i_n1", "g": "اليوم الأول"}, {"t": "نكتب الأرقام من ١ إلى ٥ على ورقة.", "i": "i_numbers", "g": "اليوم الثاني"}, {"t": "نضع بجانب كل رقم الكمية التي تناسبه.", "i": "i_n3", "g": "اليوم الثاني"}, {"t": "نكون مجموعتين ونقول أيهما أكثر وأيهما أقل.", "i": "rd_big", "g": "اليوم الثالث"}, {"t": "نكون مجموعات من ٦ إلى ١٠ ونعدها.", "i": "i_n5", "g": "اليوم الرابع"}, {"t": "نرسم مجموعتنا المفضلة ونكتب عددها.", "i": "i_pencils", "g": "اليوم الخامس"}, {"t": "نعرض لوحتنا على الأسرة ونحكي ماذا تعلمنا.", "i": "i_board", "g": "اليوم الخامس"}], "safety": "نعمل بإشراف شخص بالغ ونختار أشياء كبيرة وآمنة فقط، ونبتعد عن الأشياء الصغيرة التي قد تدخل الفم.", "outcome": "أعد الكميات وأقارن بينها وأكتب الأرقام.", "adult": true, "skills": ["العد", "مقارنة الكميات", "كتابة الأرقام"], "qs": [{"q": "إذا كان في مجموعة ٧ أشياء وفي الأخرى ٤ أشياء، أي مجموعة أكثر؟", "o": ["المجموعة التي فيها ٧", "المجموعة التي فيها ٤", "متساويتان"], "why": "العدد ٧ أكبر من العدد ٤ فالمجموعة الأولى أكثر."}, {"q": "كيف نعد الأشياء بدقة؟", "o": ["نلمس كل شيء مرة واحدة ونعد", "نعد بسرعة دون لمس", "نخمن العدد"], "why": "نلمس كل شيء مرة واحدة حتى لا ننسى ولا نكرر."}], "reflect": "ما المجموعة التي أعجبتك ولماذا؟ وكيف عرفت أي المجموعتين أكثر؟", "parent": "اترك طفلك يعد بنفسه وصحح بهدوء إن أخطأ. اسأله كم عندنا؟ وأيهما أكثر؟ ولا تقارنه بغيره.", "res": [{"label": "أنشطة المكتبة", "href": "activities/"}, {"label": "بطاقات المكتبة التعليمية", "href": "cards/"}]}$j$::jsonb,'{}'::jsonb,false,'draft',102) on conflict (slug) do nothing;
insert into public.proj_items(slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order) values ('pj_mo_plant','project','science','project','أراقب نمو نبتتي','x_plant',array['g2','g3','g4']::text[],'العلوم','الملاحظة والتسجيل والمقارنة','mid','نزرع نبتة ونلاحظها ونسجل نموها أربعة أسابيع في مراحل صغيرة.','أن أراقب نمو نبتة وأسجل ملاحظاتي كل أسبوع ثم أقارن بين المراحل.',15,'monthly',$j${"goal": "أن أراقب نمو نبتة وأسجل ملاحظاتي كل أسبوع ثم أقارن بين المراحل.", "tools": ["وعاء أو كوب نظيف", "تربة", "بذور فول أو حمص", "ماء", "مسطرة", "دفتر ملاحظات وقلم"], "steps": [{"t": "نملأ الوعاء بالتربة ونضع فيه البذرة على عمق صغير.", "i": "x_soil", "p": "ابق بجانب الطفل أثناء التعامل مع التربة.", "g": "الأسبوع الأول"}, {"t": "نسقي البذرة بقليل من الماء ونضع الوعاء قرب نافذة.", "i": "x_wcan", "g": "الأسبوع الأول"}, {"t": "نكتب اسم نبتتنا وتاريخ الزراعة على بطاقة.", "i": "i_notebook", "g": "الأسبوع الأول"}, {"t": "نلاحظ النبتة ونقيس طولها بالمسطرة ونكتب القياس.", "i": "i_ruler", "g": "الأسبوع الثاني"}, {"t": "نرسم النبتة كما نراها ونسجل لون الأوراق.", "i": "i_brush", "g": "الأسبوع الثاني"}, {"t": "نختار شيئا واحدا نغيره مثل مكان الوعاء ونتوقع ماذا سيحدث.", "i": "i_bulb", "p": "اسأله عن توقعه ولا تعطه الجواب.", "g": "الأسبوع الثالث"}, {"t": "نسجل القياس مرة أخرى ونقارنه بالأسبوع الماضي.", "i": "i_chart", "g": "الأسبوع الثالث"}, {"t": "نرتب قياساتنا ورسوماتنا في جدول واضح.", "i": "i_board", "g": "الأسبوع الرابع"}, {"t": "نحكي لأسرتنا كيف نمت نبتتنا وما الذي تعلمناه.", "i": "i_sound", "g": "الأسبوع الرابع"}], "safety": "نعمل بإشراف شخص بالغ ونغسل أيدينا بعد لمس التربة، ولا نضع البذور في الفم. نستعمل التربة والماء فقط.", "outcome": "أراقب نبتة وأسجل قياساتها وأقارن بينها.", "adult": true, "skills": ["الملاحظة", "القياس بالمسطرة", "تسجيل الأرقام", "المقارنة"], "qs": [{"q": "ماذا نفعل بعد قياس طول النبتة؟", "o": ["نكتب القياس في الدفتر", "ننسى القياس", "نهمل النبتة"], "why": "نسجل القياس حتى نقارنه في الأسبوع القادم."}, {"q": "لماذا نغير شيئا واحدا فقط في التجربة؟", "o": ["لنعرف سبب التغير", "لأنه أسهل فقط", "لا يهم"], "why": "تغيير شيء واحد يوضح لنا سبب ما حدث."}], "reflect": "ماذا لاحظت في نبتتك هذا الشهر؟ وما الذي كان مختلفا عما توقعته؟", "parent": "ذكر طفلك بموعد القياس الأسبوعي ولا تقم به بدلا عنه. اسأل ماذا تتوقع؟ وماذا لاحظت؟ وشجعه ولا تقارنه بغيره.", "res": [{"label": "تجارب علمية من المكتبة", "href": "experiments/"}, {"label": "الموسوعة", "href": "wiki/"}]}$j$::jsonb,'{}'::jsonb,false,'draft',103) on conflict (slug) do nothing;
insert into public.proj_items(slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order) values ('pj_wk_shapes','project','math','project','الأشكال حولي','rd_circle_blue',array['a4','a5','a6']::text[],'الرياضيات','التعرف على الأشكال الهندسية','easy','نبحث عن الأشكال في بيتنا خلال أسبوع ونصنع منها صورة جميلة.','أن أجد الدائرة والمربع والمثلث حولي وأسميها وأصنع صورة منها.',15,'weekly',$j${"goal": "أن أجد الدائرة والمربع والمثلث حولي وأسميها وأصنع صورة منها.", "tools": ["ورق ملون", "صمغ أو شريط لاصق", "قلم رصاص", "أقلام تلوين"], "steps": [{"t": "نبحث في البيت عن أشياء على شكل دائرة ونسميها.", "i": "rd_circle_red", "p": "امش معه ولا تدله على الأشياء مباشرة.", "g": "اليوم الأول"}, {"t": "نرسم ثلاث دوائر مما وجدنا.", "i": "i_pencil", "g": "اليوم الأول"}, {"t": "نبحث عن المربعات والمستطيلات ونعد ما وجدنا.", "i": "rd_square_green", "g": "اليوم الثاني"}, {"t": "نبحث عن المثلثات في البيت وفي الصور.", "i": "rd_triangle_yellow", "g": "اليوم الثالث"}, {"t": "يجهز الكبير أشكالا من الورق الملون بإشراف شخص بالغ، ونختار منها ما نريد.", "i": "x_paper", "p": "الكبير هو من يقص الورق.", "g": "اليوم الرابع"}, {"t": "نلصق الأشكال لنكون بيتا أو سيارة أو وجها مبتسما.", "i": "i_puzzle", "g": "اليوم الرابع"}, {"t": "نعرض لوحتنا ونسمي كل شكل فيها.", "i": "i_board", "g": "اليوم الخامس"}], "safety": "نعمل بإشراف شخص بالغ ويقوم الكبير بأي قص للورق، ونستعمل أشياء كبيرة وآمنة.", "outcome": "أسمي الأشكال الهندسية وأصنع بها صورة.", "adult": true, "skills": ["تسمية الأشكال", "التصنيف", "التركيب والإبداع"], "qs": [{"q": "ما الشكل الذي ليس له زوايا؟", "o": ["الدائرة", "المربع", "المثلث"], "why": "الدائرة مستديرة وليس لها زوايا."}, {"q": "كم ضلعا للمثلث؟", "o": ["٣", "٤", "٥"], "why": "المثلث له ثلاثة أضلاع."}], "reflect": "ما أكثر شكل وجدته حولك؟ وأي شكل استعملته أكثر في لوحتك؟", "parent": "امش مع طفلك في البيت واسأله ماذا ترى؟ وما شكله؟ ولا تقص عنه بنفسك. شجعه على كل شكل وجده ولا تقارنه بغيره.", "res": [{"label": "أنشطة المكتبة", "href": "activities/"}, {"label": "بطاقات المكتبة التعليمية", "href": "cards/"}]}$j$::jsonb,'{}'::jsonb,false,'draft',104) on conflict (slug) do nothing;
insert into public.proj_items(slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order) values ('pj_mo_reuse','project','nature','project','إعادة استخدام المواد','x_recbin',array['g3','g4']::text[],'البيئة','التخطيط وإعادة الاستخدام','mid','نحول مواد نظيفة من البيت إلى مجسم مفيد في أربعة أسابيع.','أن أخطط وأصنع شيئا مفيدا من مواد كنا سنرميها، وأشرح كيف قللنا النفايات.',25,'monthly',$j${"goal": "أن أخطط وأصنع شيئا مفيدا من مواد كنا سنرميها، وأشرح كيف قللنا النفايات.", "tools": ["علب كرتون نظيفة وجافة", "علب بلاستيكية نظيفة", "شريط لاصق", "أقلام تلوين", "ورق وقلم", "صمغ"], "steps": [{"t": "نجمع مواد نظيفة وجافة من البيت ونضعها في صندوق.", "i": "x_box", "p": "اختر معه مواد خالية من الحواف الخشنة.", "g": "الأسبوع الأول"}, {"t": "نصنف المواد إلى ورق وكرتون وبلاستيك.", "i": "x_recbin", "g": "الأسبوع الأول"}, {"t": "نفكر في شيء مفيد نصنعه مثل منظم أقلام أو بيت للألعاب.", "i": "i_bulb", "g": "الأسبوع الثاني"}, {"t": "نرسم خطة بسيطة ونكتب المواد التي نحتاجها.", "i": "i_notebook", "g": "الأسبوع الثاني"}, {"t": "يقص الكبير الكرتون إن لزم بإشراف شخص بالغ، ونجهز القطع.", "i": "x_paper", "p": "الكبير هو من يقص.", "g": "الأسبوع الثالث"}, {"t": "نركب القطع بالصمغ والشريط اللاصق ونزينها بالألوان.", "i": "i_brush", "g": "الأسبوع الثالث"}, {"t": "نختبر مجسمنا ونتأكد أنه مفيد وثابت.", "i": "i_search", "g": "الأسبوع الرابع"}, {"t": "نعرض مجسمنا ونشرح كيف قللنا النفايات في بيتنا.", "i": "i_sound", "g": "الأسبوع الرابع"}], "safety": "نعمل بإشراف شخص بالغ ونستعمل ورقا وكرتونا وعلبا بلاستيكية نظيفة فقط، ولا نلمس أي شيء له حواف خشنة.", "outcome": "أعيد استخدام مواد نظيفة وأصنع بها شيئا مفيدا.", "adult": true, "skills": ["التخطيط", "إعادة الاستخدام", "التنفيذ خطوة بخطوة", "الاهتمام بالبيئة"], "qs": [{"q": "لماذا نعيد استخدام المواد؟", "o": ["لنقلل النفايات ونحافظ على البيئة", "لنرمي أكثر", "لا فائدة منها"], "why": "إعادة الاستخدام تقلل ما نرميه وتحمي بيئتنا."}, {"q": "من يقوم بقص الكرتون؟", "o": ["الشخص البالغ", "الطفل وحده", "لا أحد"], "why": "القص عمل الكبير حفاظا على سلامة الطفل."}], "reflect": "ما الذي أعجبك في مجسمك؟ وكيف يمكنك أن تقلل النفايات في بيتك؟", "parent": "ساعد طفلك في الأسئلة ولا تصنع المجسم عنه. تول القص وحدك، ودعه يخطط وينفذ الباقي. شجعه ولا تقارنه بغيره.", "res": [{"label": "تجارب علمية من المكتبة", "href": "experiments/"}, {"label": "الحياة والبيئة", "href": "life/"}]}$j$::jsonb,'{}'::jsonb,false,'draft',105) on conflict (slug) do nothing;
